const raw = $input.item.json || {};
const extracted = raw.extracted_params || {};

const project_id = raw.project_id || extracted.project_id || null;
const episode_no = Number(raw.episode_no || raw.episode_number || extracted.episode_number || 1);
const season_no = Number(raw.season_no || raw.season_number || raw.current_season || 1);

const rawIntent = (raw.intent || raw.downstream_command || 'AUTO_QC').toString().toUpperCase().trim();
const qc_intent = (rawIntent === 'MANUAL_APPROVE' || rawIntent === 'APPROVE_QC') ? 'MANUAL_APPROVE' : 'AUTO_QC';

const media_url = raw.media_url || raw.final_video_url || raw.output_media?.master_video_url || raw.output_media?.final_video_url || null;
const file_size = Number(raw.file_size || raw.output_media?.file_size_bytes || 0);
const duration_sec = Number(raw.duration_sec || raw.output_media?.duration_sec || 0);
const sessionId = (raw.sessionId || `sess_${$execution.id}`).toString();

if (!project_id) {
  throw new Error('WF-11 Error: project_id is strictly required (Rule 5 Project Isolation).');
}

return { json: { ...raw, project_id, episode_no, season_no, qc_intent, media_url, file_size, duration_sec, sessionId, evaluated_at: $now.toISOString() } };

const base = $('Input Normalizer & QC Intent Resolver').item.json;
const rawEp = $input.item.json;
const epRow = Array.isArray(rawEp) ? rawEp[0] : (rawEp && rawEp.episode_no !== undefined ? rawEp : {});

const outputMedia = (epRow?.output_media && typeof epRow.output_media === 'object') ? epRow.output_media : {};
const scriptJson = (epRow?.script_json && typeof epRow.script_json === 'object') ? epRow.script_json : {};
const scenes = Array.isArray(scriptJson.scenes) ? scriptJson.scenes : [];

const resolvedUrl = (base.media_url || outputMedia.final_video_url || outputMedia.master_video_url || '').toString().trim();
const resolvedSize = Number(base.file_size || outputMedia.file_size_bytes || 0);
const expectedDuration = scenes.reduce((acc, s) => acc + Number(s.duration_sec || 5), 0) || 15;
const actualDuration = Number(base.duration_sec || outputMedia.duration_sec || expectedDuration);

const MIN_FILE_SIZE_BYTES = Number($env.QC_MIN_FILE_SIZE_BYTES || 1048576);
const failures = [];

if (!resolvedSize || resolvedSize < MIN_FILE_SIZE_BYTES) {
  failures.push(`File size validation failed: ${resolvedSize} bytes is below minimum 1MB (${MIN_FILE_SIZE_BYTES} bytes).`);
}

if (!/^https?:\/\/.+\.(mp4|mov|mkv|webm)(\?.*)?$/i.test(resolvedUrl)) {
  failures.push(`Invalid master video URL structure: '${resolvedUrl || 'EMPTY'}'.`);
}

const durationDelta = Math.abs(actualDuration - expectedDuration);
if (actualDuration <= 0 || (expectedDuration > 0 && durationDelta > expectedDuration * 0.35)) {
  failures.push(`Duration mismatch: actual=${actualDuration}s vs expected=${expectedDuration}s.`);
}

if (!epRow?.title && !scriptJson?.title) {
  failures.push('Metadata incomplete: Episode title is missing.');
}

const qc_passed = failures.length === 0;
const next_qc_status = qc_passed ? 'PENDING_HUMAN_APPROVAL' : 'REJECTED';

return {
  json: {
    ...base, episode_title: epRow?.title || scriptJson?.title || `Episode ${base.episode_no}`,
    resolved_media_url: resolvedUrl, resolved_file_size: resolvedSize, expected_duration_sec: expectedDuration, actual_duration_sec: actualDuration,
    qc_passed, next_qc_status, qc_failures: failures,
    human_approval_task: {
      project_id: base.project_id, episode_no: base.episode_no, action_type: 'QC_HUMAN_APPROVAL', review_type: 'AUTO_QC_PASSED_AWAITING_HUMAN', status: 'MANUAL_REVIEW',
      action_payload: { media_url: resolvedUrl, file_size_bytes: resolvedSize, duration_sec: actualDuration, checked_at: base.evaluated_at }
    },
    wf13_retry_task: {
      project_id: base.project_id, episode_no: base.episode_no, action_type: 'REGENERATE_EPISODE', review_type: 'QC_REJECTED_AUTO_HEAL', status: 'FAILED', retry_count: 0,
      action_payload: { failed_workflow: 'WF-11', qc_failures: failures, media_url: resolvedUrl, file_size_bytes: resolvedSize, rejected_at: base.evaluated_at }
    }
  }
};

const base = $('Input Normalizer & QC Intent Resolver').item.json;

if (base.qc_intent === 'MANUAL_APPROVE') {
  const msg = [
    `✅ **WF-11: Human QC Approval Committed (Rule 18)!**`,
    `• **Project ID:** \`${base.project_id}\` | **Episode:** ${base.episode_no}`,
    `• **QC Status:** \`APPROVED\` | **Episode State:** \`QC_APPROVED\``,
    `• Episode ab **WF-07 (Publisher)** ke liye unlocked hai.`
  ].join('\n');
  return { json: { ok: true, status: 'QC_APPROVED', qc_status: 'APPROVED', workflow_name: 'WF-11', execution_id: $execution.id, project_id: base.project_id, episode_no: base.episode_no, output: msg, text: msg } };
}

const autoState = $('Automated QC Inspector').item.json;
if (autoState.qc_passed) {
  const passMsg = [
    `🔎 **WF-11: Automated QC Checks PASSED!**`,
    `• **Episode:** ${autoState.episode_no} (${autoState.episode_title})`,
    `• **File Size:** ${(autoState.resolved_file_size / 1048576).toFixed(2)} MB (>= 1MB Required)`,
    `• **Duration:** ${autoState.actual_duration_sec}s (Expected: ${autoState.expected_duration_sec}s)`,
    `• **Next Step (Rule 18):** Marked \`PENDING_HUMAN_APPROVAL\` in \`episodes\` & queued in \`pending_actions\`.`
  ].join('\n');
  return { json: { ok: true, status: 'PENDING_HUMAN_APPROVAL', qc_status: 'PENDING_HUMAN_APPROVAL', workflow_name: 'WF-11', execution_id: $execution.id, project_id: base.project_id, episode_no: base.episode_no, output: passMsg, text: passMsg } };
}

const failMsg = [
  `🛑 **WF-11: Automated QC REJECTED — Dispatched to WF-13 Healer!**`,
  `• **Episode:** ${autoState.episode_no}`,
  `• **Failures Detected:**`,
  ...autoState.qc_failures.map(f => `  - ${f}`),
  `• **Action Taken:** \`episodes.qc_status = REJECTED\` & job queued in \`pending_actions\` (\`status = FAILED\`) for **WF-13 Retry Manager**.`
].join('\n');

return { json: { ok: false, status: 'QC_REJECTED', qc_status: 'REJECTED', workflow_name: 'WF-11', execution_id: $execution.id, project_id: base.project_id, episode_no: base.episode_no, qc_failures: autoState.qc_failures, output: failMsg, text: failMsg } };

